from collections import namedtuple
from lxml import objectify


class ScfcValidationReport(object):
    def __init__(self, path):
        self.messages = self._parse(path)

    def __getitem__(self, item):
        return self.messages[item]

    def __len__(self):
        return len(self.messages)

    def _parse(self, path):
        return [self._parse_message_node(message_node)
                for message_node in objectify.parse(path).getroot().message
                if not self._is_summary_message(message_node)]

    def _parse_message_node(self, message_node):
        dist_name = message_node.p[1].text
        text = message_node.p[2].text
        status = message_node.p[3].text
        details = message_node.p[4].text
        return ScfcValidationMessage(status=status, dist_name=dist_name, text=text, details=details)

    def _is_summary_message(self, message_node):
        return message_node.p[0].attrib['name'] == 'lastFeedback'


class ScfcValidationMessage(
        namedtuple('ScfcValidationMessage', ['status', 'dist_name', 'text', 'details'])):

    def is_error(self):
        """Returns true if this is an error message, or false if it is a warning"""
        return self.status == 'Error'

    def is_warning(self):
        """Returns true if this is a warning message, or false if it is an error"""
        return self.status == 'Warning'
